/*
 * ╔══════════════════════════════════════════════╗
 *    C PROGRAMMING - TEMPERATURE CONVERTER PROGRAM
 *           Bro Code Tutorial | My Notes
 * ╚══════════════════════════════════════════════╝
 *
 * Concepts practiced:
 *   -> char input with scanf("%c")
 *   -> if/else if/else with char comparison
 *   -> float arithmetic with conversion formula
 *
 * FORMULAS:
 *   C to F -> fahrenheit = (celsius * 9/5) + 32
 *   F to C -> celsius    = (fahrenheit - 32) * 5/9
 *
 * NOTE: use 9/5 carefully — in C, integer division
 *   9/5 = 1 (truncated), BUT since celsius is float
 *   the compiler promotes it to float automatically.
 *   To be safe you can write 9.0/5.0 explicitly.
 */

int main() {

    char  choice     = '\0';
    float fahrenheit = 0.0f;
    float celsius    = 0.0f;

    printf("--- Temperature Conversion Program ---\n");
    printf("C. Celsius to Fahrenheit\n");
    printf("F. Fahrenheit to Celsius\n");
    printf("Is the temp in Celsius (C) or Fahrenheit (F)?: ");
    scanf(" %c", &choice); // space before %c clears leftover '\n'

    if(choice == 'C') {
        // Celsius -> Fahrenheit
        printf("Enter the temperature in Celsius: ");
        scanf("%f", &celsius);
        fahrenheit = (celsius * 9/5) + 32;
        printf("%.1f C is equal to %.1f F\n", celsius, fahrenheit);
    }
    else if(choice == 'F') {
        // Fahrenheit -> Celsius
        printf("Enter the temperature in Fahrenheit: ");
        scanf("%f", &fahrenheit);
        celsius = (fahrenheit - 32) * 5/9;
        printf("%.1f F is equal to %.1f C\n", fahrenheit, celsius);
    }
    else {
        printf("Invalid choice! Please enter C or F\n");
    }

    return 0;
}

#include <stdio.h>

int main() {

    // CALCULATOR PROGRAM

    char   operator = '\0';
    double num1     = 0.0;
    double num2     = 0.0;
    double result   = 0.0;

    printf("Enter the First number: ");
    scanf("%lf", &num1);

    printf("Enter the operator (+ - * /): ");
    scanf(" %c", &operator); // space before %c clears leftover '\n'

    printf("Enter the Second number: ");
    scanf("%lf", &num2);

    /* ═══════════════════════════════════════════════
     * SWITCH STATEMENT
     * ═══════════════════════════════════════════════
     * Checks operator character against each case.
     * break -> stops fall-through to next case.
     * default -> runs if no case matches.
     *
     * WARNING: forgetting break causes fall-through
     * meaning it runs the next case automatically!
     */

    switch(operator) {
        case '+':
            result = num1 + num2;
            break;
        case '-':
            result = num1 - num2;
            break;
        case '*':
            result = num1 * num2;
            break;
        case '/':
            if(num2 == 0) {
                printf("You can't divide by zero!\n");
            }
            else {
                result = num1 / num2;
            }
            break; // THIS was missing — caused fall-through to default
        default:
            printf("Invalid Operator!\n");
    }

    printf("Result: %.4lf\n", result);

    return 0;
}

