/*
 * ╔══════════════════════════════════════════════╗
 *       C PROGRAMMING - ROCK PAPER SCISSORS
 *           Bro Code Tutorial | My Notes
 * ╚══════════════════════════════════════════════╝
 */

/* ═══════════════════════════════════════════════
 * FUNCTION PROTOTYPES
 * ═══════════════════════════════════════════════
 * Declared above main() so compiler knows
 * they exist before they are called.
 */

int  getComputerChoice();                        // returns 1, 2, or 3 randomly
int  getUserChoice();                            // returns user's menu choice
void checkWinner(int userChoice, int computerChoice); // prints result, returns nothing

/* ═══════════════════════════════════════════════
 * MAIN
 * ═══════════════════════════════════════════════ */

int main() {

    srand(time(NULL)); // seed random number generator once

    printf("*** ROCK PAPER SCISSORS ***\n");

    int userChoice     = getUserChoice();
    int computerChoice = getComputerChoice();

    // print what user chose
    switch(userChoice) {
        case 1: printf("You chose Rock!\n");     break;
        case 2: printf("You chose Paper!\n");    break;
        case 3: printf("You chose Scissors!\n"); break;
    }

    // print what computer chose
    switch(computerChoice) {
        case 1: printf("Computer chose Rock!\n");     break;
        case 2: printf("Computer chose Paper!\n");    break;
        case 3: printf("Computer chose Scissors!\n"); break;
    }

    checkWinner(userChoice, computerChoice);

    return 0;
}

/* ═══════════════════════════════════════════════
 * FUNCTION DEFINITIONS
 * ═══════════════════════════════════════════════ */

// returns random int 1-3 (1=Rock, 2=Paper, 3=Scissors)
int getComputerChoice() {
    return (rand() % 3) + 1;
}

// shows menu, reads and returns user's choice
int getUserChoice() {
    int choice = 0;

    printf("1. Rock\n");
    printf("2. Paper\n");
    printf("3. Scissors\n");
    printf("Choose: ");
    scanf("%d", &choice);

    return choice;
}

/* ═══════════════════════════════════════════════
 * checkWinner() — TWO WAYS TO WRITE WIN CONDITION
 * ═══════════════════════════════════════════════
 *
 * WAY 1 (used below): separate if/else for each win
 *   -> easier to read, more explicit
 *
 * WAY 2 (commented out): combine all wins with || (OR)
 *   -> shorter, but harder to read at a glance
 *   -> || means "or" — true if ANY condition is true
 *
 *   else if((userChoice == 1 && computerChoice == 3) ||
 *           (userChoice == 2 && computerChoice == 1) ||
 *           (userChoice == 3 && computerChoice == 2)) {
 *       printf("You WIN!\n");
 *   }
 */

void checkWinner(int userChoice, int computerChoice) {

    if(userChoice == computerChoice) {
        printf("It's a TIE!\n");
    }
    else if(userChoice == 1 && computerChoice == 3) {
        printf("You WIN! Rock beats Scissors\n");
    }
    else if(userChoice == 2 && computerChoice == 1) {
        printf("You WIN! Paper beats Rock\n");
    }
    else if(userChoice == 3 && computerChoice == 2) {
        printf("You WIN! Scissors beats Paper\n");
    }
    else {
        printf("You LOSE!\n");
    }
}

#include <stdio.h>

/*
 * ╔══════════════════════════════════════════════╗
 *          C PROGRAMMING - BANKING PROGRAM
 *           Bro Code Tutorial | My Notes
 * ╚══════════════════════════════════════════════╝
 */

/* ═══════════════════════════════════════════════
 * FUNCTION PROTOTYPES
 * ═══════════════════════════════════════════════ */

void  checkBalance(float balance);
float deposit();
float withdraw(float balance);

/* ═══════════════════════════════════════════════
 * MAIN
 * ═══════════════════════════════════════════════ */

int main() {

    int   choice  = 0;
    float balance = 0.0f;

    printf("*** WELCOME TO THE BANK ***");

    do {
        printf("\nSelect an option:\n");
        printf("\n1. Check Balance\n");
        printf("2. Deposit Money\n");
        printf("3. Withdraw Money\n");
        printf("4. Exit\n");
        printf("\nEnter your choice: ");
        scanf("%d", &choice);

        switch(choice) {
            case 1:
                checkBalance(balance);
                break;
            case 2:
                balance += deposit();        // balance = balance + deposit()
                break;
            case 3:
                balance -= withdraw(balance); // balance = balance - withdraw()
                break;
            case 4:
                printf("\nThank you for using the bank!\n");
                break;
            default:
                printf("\nInvalid choice! Please select 1 - 4\n");
        }
    } while(choice != 4);

    return 0;
}

/* ═══════════════════════════════════════════════
 * FUNCTION DEFINITIONS
 * ═══════════════════════════════════════════════ */

// prints current balance — void, returns nothing
void checkBalance(float balance) {
    printf("\nYour current balance is: $%.2f\n", balance);
}

// reads deposit amount, validates, returns amount to add
float deposit() {
    float amount = 0.0f;

    printf("\nEnter amount to deposit: $");
    scanf("%f", &amount);

    if(amount < 0) {
        printf("Invalid amount!\n");
        return 0.0f; // return 0 so balance doesn't change
    }
    else {
        printf("Successfully deposited $%.2f\n", amount);
    }

    return amount;
}

// reads withdraw amount, validates, returns amount to subtract
float withdraw(float balance) {
    float amount = 0.0f;

    printf("\nEnter amount to withdraw: $");
    scanf("%f", &amount);

    if(amount < 0) {
        printf("Invalid amount!\n");
        return 0.0f; // return 0 so balance doesn't change
    }
    else if(amount > balance) {
        printf("Insufficient funds! Your balance is $%.2f\n", balance);
        return 0.0f; // return 0 so balance doesn't change
    }                // ERROR WAS HERE — missing } before else
    else {
        printf("Successfully withdrew $%.2f\n", amount);
        return amount;
    }
}

#include <stdio.h>
#include <ctype.h>

/*
 * ╔══════════════════════════════════════════════╗
 *           C PROGRAMMING - QUIZ GAME
 *           Bro Code Tutorial | My Notes
 * ╚══════════════════════════════════════════════╝
 *
 * Concepts practiced:
 *   -> 2D array of strings for questions and options
 *   -> char array for answer key
 *   -> toupper() from <ctype.h> to accept a or A
 *   -> sizeof to get question count automatically
 *   -> for loop to cycle through all questions
 *
 * WARNING: string literals placed next to each other
 * WITHOUT a comma get merged into ONE string by compiler
 *   WRONG: {"Hello" "World"}  -> "HelloWorld" (one string)
 *   RIGHT: {"Hello", "World"} -> two separate strings
 */

int main() {

    // each string is one question — MUST have commas between them
    char questions[][100] = {
        "What is the largest planet in the solar system?",
        "What is the hottest planet?",
        "What planet has the most moons?",
        "Is the Earth flat?"
    };

    // each string holds all options for one question
    char options[][100] = {
        "A. Jupiter\nB. Saturn\nC. Uranus\nD. Neptune",
        "A. Mercury\nB. Venus\nC. Earth\nD. Mars",
        "A. Earth\nB. Mars\nC. Jupiter\nD. Saturn",
        "A. Yes\nB. No\nC. Maybe\nD. Sometimes"
    };

    // correct answer for each question (index matched)
    char answerKey[] = {'A', 'B', 'D', 'B'};

    // sizeof trick to get count automatically
    // if you add more questions later, no need to update this
    int questionCount = sizeof(questions) / sizeof(questions[0]);

    char guess = '\0';
    int  score = 0;

    printf("*** QUIZ GAME ***\n");

    for(int i = 0; i < questionCount; i++) {
        printf("\n%s\n",   questions[i]); // print question
        printf("\n%s\n",   options[i]);   // print options
        printf("\nEnter your choice: ");
        scanf(" %c", &guess);             // space before %c clears '\n'

        guess = toupper(guess); // convert a->A, b->B so both work

        if(guess == answerKey[i]) {
            printf("CORRECT!\n");
            score++;
        }
        else {
            printf("Wrong! The answer was %c\n", answerKey[i]);
        }
    }

    printf("\nYour score: %d out of %d\n", score, questionCount);

    return 0;
}

